var t=`0974-tteokbokki`;var s=`world-0974`;var a=`KR`;var n=`east-asia`;var o=8;var g=26;var h={en:`Tteokbokki`,ua:`Ттокпоккі`};var c={en:`Tteokbokki is a South Korea dish made with gochujang, light soy sauce, tteokbokki rice cakes, fish cake. This home-scale recipe assigns measured ingredients to the steps where they are used. Rice cakes must soften thoroughly, with the spicy sauce clinging to each piece.`,ua:`Ттокпоккі, страва кухні країни Південна Корея. Основні складники: гочуджан, світлий соєвий соус, рисові палички ттокпоккі, рибна котлета. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Рисові тток потрібно повністю розм’якшити, щоб гострий соус вкрив кожен шматочок.`};var r=[{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 10 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 10 хвилин до м’якості та готовності.`,t:[`simmering`],m:10,i:[[`dashi-stock`,500,`ml`],[`gochujang`,105,`g`],[`gochugaru`,14,`g`],[`white-granulated-sugar`,35,`g`],[`light-soy-sauce`,25,`ml`]]},{en:`Simmer Korean cylindrical rice cakes and fish cake in gochujang sauce until the rice cakes are soft and the sauce thickly coats them.`,ua:`Тушкуйте корейські циліндричні рисові тток і рибні коржики в соусі кочуджан до м’якості рису та густого покриття соусом.`,t:[`stewing`],m:13,i:[[`tteokbokki-rice-cakes`,720,`g`],[`fish-cake`,200,`g`],[`white-cabbage`,180,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,85,`g`],[`white-sesame-seeds`,18,`g`]]}];var u={slug:t,id:s,country:`KR`,region:n,servings:8,minutes:26,title:h,text:c,steps:r};export{a as country,u as default,s as id,g as minutes,n as region,o as servings,t as slug,r as steps,c as text,h as title};